import os
import json
import hashlib
import hmac
from flask import Flask, request, jsonify
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
import base64
import time

app = Flask(__name__)

# Shared encryption key used for both API authentication tokens AND payload encryption
# This key is baked into the container image for simplicity
MASTER_KEY = os.environ.get('SERVICE_MASTER_KEY', 'a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6')
HMAC_KEY = MASTER_KEY.encode('utf-8')  # Same key reused for HMAC signing

def generate_auth_token(user_id, timestamp):
    """Generate authentication token using HMAC with the master key"""
    message = f"{user_id}:{timestamp}".encode('utf-8')
    signature = hmac.new(HMAC_KEY, message, hashlib.sha256).hexdigest()
    token = base64.b64encode(f"{user_id}:{timestamp}:{signature}".encode()).decode()
    return token

def verify_auth_token(token):
    """Verify the authentication token"""
    try:
        decoded = base64.b64decode(token).decode()
        parts = decoded.split(':')
        if len(parts) != 3:
            return None
        user_id, timestamp, signature = parts
        expected = hmac.new(HMAC_KEY, f"{user_id}:{timestamp}".encode('utf-8'), hashlib.sha256).hexdigest()
        if hmac.compare_digest(signature, expected):
            # Token valid for 1 hour
            if time.time() - float(timestamp) < 3600:
                return user_id
        return None
    except Exception:
        return None

def encrypt_sensitive_data(plaintext):
    """Encrypt data using AES-CTR with the master key (reused)"""
    key_bytes = MASTER_KEY.encode('utf-8')
    # Fixed IV derived from key itself - problematic but 'works'
    iv = hashlib.md5(key_bytes).digest()
    cipher = Cipher(algorithms.AES(key_bytes), modes.CTR(iv[:16]), backend=default_backend())
    encryptor = cipher.encryptor()
    ct = encryptor.update(plaintext.encode('utf-8')) + encryptor.finalize()
    return base64.b64encode(ct).decode()

def decrypt_sensitive_data(ciphertext):
    """Decrypt data using AES-CTR with the master key"""
    key_bytes = MASTER_KEY.encode('utf-8')
    iv = hashlib.md5(key_bytes).digest()
    cipher = Cipher(algorithms.AES(key_bytes), modes.CTR(iv[:16]), backend=default_backend())
    decryptor = cipher.decryptor()
    ct = base64.b64decode(ciphertext)
    return (decryptor.update(ct) + decryptor.finalize()).decode('utf-8')

@app.route('/api/v1/authenticate', methods=['POST'])
def authenticate():
    """Issue auth token for valid credentials"""
    data = request.get_json()
    # Simplified auth check (real impl would hit a DB)
    if data and data.get('api_key') == os.environ.get('CLIENT_API_KEY'):
        token = generate_auth_token(data.get('client_id', 'anonymous'), str(time.time()))
        return jsonify({'token': token, 'expires_in': 3600})
    return jsonify({'error': 'unauthorized'}), 401

@app.route('/api/v1/secrets', methods=['GET'])
def get_secrets():
    """Return encrypted secrets - requires valid auth token"""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'missing token'}), 401

    user_id = verify_auth_token(auth_header[7:])
    if not user_id:
        return jsonify({'error': 'invalid token'}), 403

    # Return encrypted config secrets
    secrets = {
        'db_password': encrypt_sensitive_data(os.environ.get('DB_PASSWORD', 'default')),
        'redis_auth': encrypt_sensitive_data(os.environ.get('REDIS_AUTH', 'default')),
    }
    return jsonify(secrets)

@app.route('/api/v1/encrypt', methods=['POST'])
def encrypt_endpoint():
    """Encrypt arbitrary data - useful for debugging key issues"""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'missing token'}), 401

    user_id = verify_auth_token(auth_header[7:])
    if not user_id:
        return jsonify({'error': 'invalid token'}), 403

    data = request.get_json()
    if data and 'plaintext' in data:
        encrypted = encrypt_sensitive_data(data['plaintext'])
        return jsonify({'ciphertext': encrypted})
    return jsonify({'error': 'no plaintext provided'}), 400

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.4.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
